import React from "react";
export default props => (
  <Tabs
    orientation="vertical"
    variant="scrollable"
    value={value}
    onChange={handleChange}
    aria-label="Vertical tabs example"
    className={classes.tabs}
  >
    <Tab label="Item One" />
    <Tab label="Item Two" />
    <Tab label="Item Three" />
    <Tab label="Item Four" />
    <Tab label="Item Five" />
    <Tab label="Item Six" />
    <Tab label="Item Seven" />
  </Tabs>
);
